select * from (select aaa.* from (







        UNION ALL



) aaa
left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS'
left join SYS_DATADICT_LIST dictccy on aaa.ccy=dictccy.ITEM_CODE and dictccy.DICT_CODE='CCY'




 order by aaa.regTradeDate DESC
)


    order by ${sort} ${direction}

mapper.sql:
select distinct /*decode(reg.is_cancel,'Y','撤销','N','有效') as effectiveStatusStr,*/ (case reg.is_cancel when 'Y' then '撤销'vwhen 'N' then '有效' end) as effectiveStatusStr, /*decode(reg.is_cancel,'N',#{VALID_STATUS_01},'Y',#{VALID_STATUS_03}) as effectiveStatus,*/ (case reg.is_cancel when 'N' then #{VALID_STATUS_01} when 'Y' then #{VALID_STATUS_03} end) as effectiveStatus, reg.totle_trade_id as busiCode, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, regAdd.EXERCISE_PRICE as exercisePrice, regAdd.redeem_Rate*100 as redeemRate, deal.accountPosition as accountPosition, reg.trade_date as regTradeDate, reg.settle_date as exerciseDate, regAdd.act_sette_date as actExerciseDate, deal.sec_manage_acct_id as secManageAcctId, deal.SEC_ACCT_NAME as secManageAcctIdStr, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.ccy as ccy, /* decode(reg.is_cancel,'Y', rr.remark,'N',reg.remark) as remark*/ ( case reg.is_cancel when 'Y' then rr.remark when 'N' then reg.remark end) as remark from reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id=regAdd.totle_trade_id inner join ( /*select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName,*/ select regdeal.totle_trade_id,group_concat(regdeal.portfolio_id) as portfolioId,group_concat(pp.portfolio_name) portfolioName, /*wm_concat(regdeal.sec_manage_acct_id) sec_manage_acct_id,wm_concat(stlinfo.SEC_ACCT_NAME) SEC_ACCT_NAME,*/ group_concat(regdeal.sec_manage_acct_id) sec_manage_acct_id,group_concat(stlinfo.SEC_ACCT_NAME) SEC_ACCT_NAME, /*nvl(sum(bb.PTL_BOND_ZHCC),0)/10000 as accountPosition*/ ifnull(sum(bb.PTL_BOND_ZHCC),0)/10000 as accountPosition from reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id left join (select a.PORTFOLIO_ID, a.FINPROD_ID,sum(CASE WHEN a.HODING_TYPE =#{A_001} THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_ZHCC from PTL_SEC_POSITION_RULE a where a.cdate = #{cdate,jdbcType=DATE} AND a.DATE_TYPE =#{DATE_TYPE_0} group by a.PORTFOLIO_ID, a.FINPROD_ID )bb on regdeal.finprod_id=bb.FINPROD_ID and regdeal.PORTFOLIO_ID=bb.PORTFOLIO_ID left join stl_sec_acct_info stlinfo on regdeal.sec_manage_acct_id=stlinfo.sec_acct_id where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id LEFT JOIN TRD_BANK_MANUAL_SETTLE_INFO T8 ON match.trd_id = T8.TRADE_ID left join reg_fin_product_deal_total rr on rr.totle_trade_id=CONCAT(reg.totle_trade_id, 'R') and rr.trade_status='03' and rr.ps='T39' and rr.is_cancel='N' where 1=1 and reg.trade_status='01' and reg.ps='T39'
AND reg.trade_date>= #{startRegDate,jdbcType=DATE}
AND reg.trade_date<= #{endRegDate,jdbcType=DATE}
AND reg.settle_date>=#{startExerDate,jdbcType=DATE}
AND reg.settle_date<=#{endExerDate,jdbcType=DATE}
and reg.ou_trader_id= #{submitUserId}
AND reg.finprod_id in
#{item}
AND reg.totle_trade_id like /*'%' || #{busiCode,jdbcType=VARCHAR} || '%'*/ CONCAT(CONCAT('%',#{busiCode,jdbcType=VARCHAR}),'%')
AND /*decode(reg.is_cancel,'N',#{VALID_STATUS_01},'Y',#{VALID_STATUS_03}) in*/ (case reg.is_cancel when 'N' then #{VALID_STATUS_01} when 'Y'then #{VALID_STATUS_03} end) in
#{item}
and reg.is_cancel='N' /*and nvl(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01}) in (#{DELIVERY_STATUS_01},#{DELIVERY_STATUS_04})*/ and ifnull(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01}) in (#{DELIVERY_STATUS_01},#{DELIVERY_STATUS_04})
and (reg.is_cancel='Y' or (reg.is_cancel='N' /*and nvl(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01})=#{DELIVERY_STATUS_02}))*/ and ifnull(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01})=#{DELIVERY_STATUS_02}))

select distinct '流程中' as effectiveStatusStr, #{VALID_STATUS_04} effectiveStatus, reg.totle_trade_id as busiCode, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, regAdd.EXERCISE_PRICE as exercisePrice, regAdd.redeem_Rate*100 as redeemRate, deal.accountPosition as accountPosition, reg.trade_date as regTradeDate, reg.settle_date as exerciseDate, regAdd.act_sette_date as actExerciseDate, deal.sec_manage_acct_id as secManageAcctId, deal.SEC_ACCT_NAME as secManageAcctIdStr, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.ccy as ccy, reg.remark as remark from wfl_reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join wfl_reg_fin_pro_deal_total_add regAdd on reg.totle_trade_id=regAdd.totle_trade_id inner join ( /*select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName, wm_concat(regdeal.sec_manage_acct_id) sec_manage_acct_id,wm_concat(stlinfo.SEC_ACCT_NAME) SEC_ACCT_NAME, nvl(sum(bb.PTL_BOND_ZHCC),0)/10000 as accountPosition*/ select regdeal.totle_trade_id,group_concat(regdeal.portfolio_id) as portfolioId,group_concat(pp.portfolio_name) portfolioName, group_concat(regdeal.sec_manage_acct_id) sec_manage_acct_id,group_concat(stlinfo.SEC_ACCT_NAME) SEC_ACCT_NAME, ifnull(sum(bb.PTL_BOND_ZHCC),0)/10000 as accountPosition from wfl_reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id left join (select a.PORTFOLIO_ID, a.FINPROD_ID,sum(CASE WHEN a.HODING_TYPE =#{A_001} THEN a.AMOUNT ELSE 0 END) AS PTL_BOND_ZHCC from PTL_SEC_POSITION_RULE a where a.cdate = #{cdate,jdbcType=DATE} AND a.DATE_TYPE =#{DATE_TYPE_0} group by a.PORTFOLIO_ID, a.FINPROD_ID )bb on regdeal.finprod_id=bb.FINPROD_ID and regdeal.PORTFOLIO_ID=bb.PORTFOLIO_ID left join stl_sec_acct_info stlinfo on regdeal.sec_manage_acct_id=stlinfo.sec_acct_id where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id where 1=1 and reg.ps='T39'
AND reg.trade_date>= #{startRegDate,jdbcType=DATE}
AND reg.trade_date<= #{endRegDate,jdbcType=DATE}
AND reg.settle_date>=#{startExerDate,jdbcType=DATE}
AND reg.settle_date<=#{endExerDate,jdbcType=DATE}
and reg.ou_trader_id=#{submitUserId}
AND reg.finprod_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND #{VALID_STATUS_04} in
#{item}
and 'regCur'=#{tabType,jdbcType=VARCHAR}

mapper.select:
SELECT   t.totle_trade_id as busiCode
from reg_fin_product_deal_total t
where t.finprod_id=#{finprodId,jdbcType=VARCHAR}
and t.settle_date=#{settleDate,jdbcType=DATE}
and  t.is_cancel='N' and t.trade_status='01'   and t.ps='T39'
union all
SELECT t.totle_trade_id as busiCode
from wfl_reg_fin_product_deal_total t
where t.finprod_id=#{finprodId,jdbcType=VARCHAR}
and t.settle_date=#{settleDate,jdbcType=DATE}
and  t.is_cancel='N' and t.trade_status='01' and t.ps='T39'
